import {businessOverview} from './business-report.js?v=0.10.0';
import {BUSINESS_DEFAULTS,businessFromCosts} from './business-model.js?v=0.10.0';
import {costComparison,COST_DEFAULTS,COST_SOURCES,COST_RESEARCH_DATE} from './cost-model.js?v=0.10.0';
const esc=v=>String(v??'').replace(/[&<>"']/g,c=>({'&':'&amp;','<':'&lt;','>':'&gt;','"':'&quot;',"'":'&#39;'}[c]));
const money=n=>n===null?'—':new Intl.NumberFormat('en-US',{style:'currency',currency:'USD'}).format(n);
const signed=n=>n===null?'—':`${n<0?'−':'+'}${money(Math.abs(n))}`;
const n=v=>Number(v.toFixed(1)).toLocaleString();
const colors={inhouse:'#275947',dd:'#b47e35',uber:'#628597',wages:'#275947',mileage:'#9db285',fees:'#b47e35',extras:'#dbcba8'};
const link=(key,label)=>`<a href="${COST_SOURCES[key]}" target="_blank" rel="noopener noreferrer">${esc(label)}</a>`;
function input(key,label,value,step='.01',max='10000'){return `<div><label for="cost-${key}">${esc(label)}</label><input type="number" inputmode="decimal" id="cost-${key}" name="${key}" min="0" max="${max}" step="${step}" value="${value}" required></div>`;}
function card(title,caption,body,wide=false){return `<section class="card chart-card ${wide?'chart-wide':''}"><h3>${esc(title)}</h3><p class="chart-caption">${esc(caption)}</p>${body}<p class="chart-readout" role="status" aria-live="polite"></p></section>`;}
function table(headers,rows){return `<details class="chart-data"><summary>View model numbers</summary><div class="table-wrap"><table><thead><tr>${headers.map(h=>`<th>${esc(h)}</th>`).join('')}</tr></thead><tbody>${rows.map(r=>`<tr>${r.map(v=>`<td>${esc(v)}</td>`).join('')}</tr>`).join('')}</tbody></table></div></details>`;}
function tooltip(text){return `data-chart-note="${esc(text)}" tabindex="0" role="button" aria-label="${esc(text)}"`;}
function comparisonBars(result){const count=result.orders||1,rows=[{label:'In-house',wages:result.wages/count,mileage:result.mileage/count,fees:0,extras:0},{label:'DoorDash Marketplace',fees:(result.dd-result.ddEquipment)/count,extras:result.ddEquipment/count},{label:'Uber Eats Marketplace',fees:(result.uber-result.uberEquipment)/count,extras:result.uberEquipment/count},{label:'DoorDash Drive',fees:result.ddDrive/count},{label:'Uber Direct',fees:result.uberDirect/count}],keys=['wages','mileage','fees','extras'],max=Math.max(1,...rows.map(r=>keys.reduce((v,k)=>v+(r[k]||0),0)));
 return `<div class="cost-bars">${rows.map(r=>{const total=keys.reduce((v,k)=>v+(r[k]||0),0);return `<button class="cost-bar" type="button" ${tooltip(`${r.label}: ${money(total)} per modeled order`)}><span>${r.label}</span><strong>${money(total)}</strong><div>${keys.map(k=>r[k]?`<i style="width:${r[k]/max*100}%;background:${colors[k]}"></i>`:'').join('')}</div></button>`;}).join('')}</div><div class="chart-legend">${[['wages','Delivery wages'],['mileage','Mileage'],['fees','Platform fees'],['extras','Equipment assumption']].map(([key,label])=>`<span><i style="background:${colors[key]}"></i>${label}</span>`).join('')}</div>${table(['Model','Period cost','Per order'],rows.map(r=>{const total=keys.reduce((v,k)=>v+(r[k]||0),0);return [r.label,money(total*result.orders),money(total)];}))}`;
}
function cumulative(result){const rows=result.cumulative,sets=[{key:'inhouse',label:'In-house'},{key:'dd',label:'DoorDash Marketplace'},{key:'uber',label:'Uber Eats Marketplace'}],max=Math.max(1,...rows.flatMap(r=>sets.map(s=>r[s.key]))),x=i=>50+(rows.length===1?245:i*490/(rows.length-1)),y=v=>205-v/max*170;let svg=`<svg class="report-svg" viewBox="0 0 600 258" role="img" aria-label="Modeled cumulative delivery costs"><title>Modeled cumulative delivery costs</title>`;
 for(let i=0;i<=4;i++){const v=max*i/4;svg+=`<line x1="50" x2="560" y1="${y(v)}" y2="${y(v)}" class="chart-gridline"/><text x="44" y="${y(v)+5}" text-anchor="end" class="chart-axis">$${Math.round(v)}</text>`;}
 for(const s of sets){svg+=`<path d="${rows.map((r,i)=>`${i?'L':'M'}${x(i)},${y(r[s.key])}`).join(' ')}" stroke="${colors[s.key]}" stroke-width="3" fill="none" ${s.key==='uber'?'stroke-dasharray="7 5"':''}/>`;rows.forEach((r,i)=>{const text=`${r.date}: ${s.label}, ${money(r[s.key])} cumulative modeled cost`;svg+=`<circle cx="${x(i)}" cy="${y(r[s.key])}" r="4" fill="${colors[s.key]}" ${tooltip(text)}><title>${esc(text)}</title></circle>`;});}
 rows.forEach((r,i)=>{if(rows.length<=8||i%Math.ceil(rows.length/7)===0||i===rows.length-1)svg+=`<text x="${x(i)}" y="235" text-anchor="middle" class="chart-axis">${r.date.slice(5)}</text>`;});return svg+'</svg>'+`<div class="chart-legend">${sets.map(s=>`<span><i style="background:${colors[s.key]}"></i>${s.label}${s.key==='uber'?' (dashed)':''}</span>`).join('')}</div>`+table(['Sample shift','In-house','DoorDash','Uber Eats'],rows.map(r=>[r.date,money(r.inhouse),money(r.dd),money(r.uber)]));
}
function sensitivity(state,shifts,result){const subtotals=[25,40,55,70,90],returns=[0,5,10,15,20],a=result.assumptions;return `<div class="heat-scroll"><div class="delivery-heatmap cost-heatmap" style="grid-template-columns:64px repeat(5,minmax(52px,1fr))"><span>Return</span>${subtotals.map(v=>`<strong>$${v}</strong>`).join('')}${returns.map(minutes=>{const test=costComparison(state,shifts,{...a,returnMinutes:minutes},{assumeAllReturns:true});return `<strong>${minutes} min</strong>${subtotals.map(price=>{const delta=test.coverageComplete?(price*a.ddRate/100+test.ddEquipment/test.orders-test.perOrder):null,text=`${minutes}-minute return, $${price} average order: in-house ${delta===null?'cost unavailable':delta>=0?'lower by '+money(delta):'higher by '+money(-delta)} per order versus DoorDash`;return `<button type="button" class="cost-sensitivity ${delta===null?'':delta>=0?'cost-lower':'cost-higher'}" ${tooltip(text)}>${signed(delta)}</button>`;}).join('')}`;}).join('')}</div></div><p class="muted">Per-order difference versus your DoorDash rate assumption. Green means in-house costs less; amber means more. This sensitivity chart replaces every return with the row’s assumption, including recorded returns. Zero minutes is a lower bound, not a measured drive home.</p>`;}
function basketBreakdown(a,result){const baskets=[{name:'Solo',price:a.soloPrice,share:a.soloShare,description:'1 Phad Thai ($17) + 1 Thai iced tea ($4.50)'},{name:'Two people',price:a.duoPrice,share:a.duoShare,description:'2 mains ($34) + rice ($3) + veggie rolls ($10) + 2 teas ($9)'},{name:'Family',price:a.familyPrice,share:a.familyShare,description:'4 mains ($68) + 2 rice ($6) + 2 veggie rolls ($20) + 2 ice creams ($11)'}];return `<div class="cost-baskets">${baskets.map(b=>`<article><span class="eyebrow">${b.name}</span><strong>${money(b.price)}</strong><p>${esc(b.description)}</p><small>${b.share}% assumed share${b.price!==({Solo:21.5,'Two people':56,Family:105}[b.name])?' · custom basket total':''}</small></article>`).join('')}</div><p class="muted">Illustrative base-price chicken/tofu baskets from the ${link('menu','dinner menu')}, checked ${COST_RESEARCH_DATE}; no protein upgrades, tax, tips or customer fees. These baskets and their mix are assumptions, not an observed average. The model holds travel time constant across basket sizes.</p>${table(['Basket','Subtotal assumption','DoorDash fee assumption','Uber fee assumption'],baskets.map(b=>[b.name,money(b.price),money(b.price*a.ddRate/100),money(b.price*result.uberEffectiveRate/100)]))}`;}
export function costLab(state,shifts,raw=COST_DEFAULTS,businessInputs=BUSINESS_DEFAULTS){const r=costComparison(state,shifts,raw),a=r.assumptions,delta=r.ddDifference;return `<div class="cost-demo-banner"><strong>HYPOTHETICAL · SAMPLE RECORDS ONLY</strong><p>Same-order cost comparison for these fictional driver shifts. It does not measure Srivilai’s actual savings, sales or profit. No real shift records or pay settings are changed.</p></div>${businessOverview(state,shifts,raw,businessInputs)}<details class="card cost-controls"><summary>Adjust wages, order sizes & platform fees</summary><form id="cost-form"><h2>Change the assumptions.</h2><p class="muted">Recalculate to explore a scenario. Inputs stay in this session and are not added to real reports.</p><div class="form-grid">${input('wage','Delivery wage ($ / hour)',a.wage,'.01','500')}${input('mileageRate','Reimbursement ($ / mile)',a.mileageRate,'.01','20')}${input('returnMinutes','Assumed return minutes / trip',a.returnMinutes,'1','120')}</div><p class="muted">Default wage: Seattle’s published 2026 ${link('wage','$21.30 minimum')}. Mileage: your stated $0.73. We count each trip once, merge overlapping time intervals, and cap them at shift end. Kitchen / idle time is excluded. Recorded restaurant-return times are used when valid. Older runs without a usable return use the minutes assumption above. Sample timestamps are fictional, including recorded returns.</p><h3>What does an average order look like?</h3><div class="cost-mix-inputs">${[['Solo','soloPrice','soloShare'],['Two people','duoPrice','duoShare'],['Family','familyPrice','familyShare']].map(([label,price,share])=>`<div><h4>${label}</h4>${input(price,'Basket subtotal ($)',a[price],'.50','2000')}${input(share,'Share of orders (%)',a[share],'1','100')}</div>`).join('')}</div><div class="actions"><button type="button" data-cost-preset="solo">Solo-heavy mix</button><button type="button" data-cost-preset="balanced">Balanced mix</button><button type="button" data-cost-preset="family">Family-heavy mix</button></div><details class="cost-assumptions"><summary>Platform plans, equipment and startup assumptions</summary><p>Seattle guidance requires a 15% delivery-services option. Additional agreed services can cost more. Higher national package examples are not a quote for Srivilai. ${link('seattle','Seattle guidance')}</p><div class="form-grid"><div><label for="cost-ddRate">DoorDash Marketplace fee assumption</label><select id="cost-ddRate" name="ddRate">${[[15,'15% · Basic / Seattle baseline'],[25,'25% · published US Plus package'],[30,'30% · published US Premier package']].map(([v,label])=>`<option value="${v}" ${a.ddRate===v?'selected':''}>${label}</option>`).join('')}</select></div><div><label for="cost-uberRate">Uber Eats Marketplace fee assumption</label><select id="cost-uberRate" name="uberRate">${[[15,'15% · Seattle Lite starting rate'],[25,'25% · published Plus package'],[30,'30% · published Premium package']].map(([v,label])=>`<option value="${v}" ${a.uberRate===v?'selected':''}>${label}</option>`).join('')}</select></div>${input('uberOneShare','Uber One orders (%) — Plus only',a.uberOneShare,'1','100')}</div><p class="muted">Uber Plus adds 5 percentage points on Uber One orders; the share field only affects Plus. Platform fees may vary by contract and city. Introductory promotions and optional advertising are not modeled.</p><label class="checkbox-label"><input type="checkbox" name="ddTablet" ${a.ddTablet?'checked':''}> Include optional DoorDash tablet ($6 / week after trial)</label><div class="form-grid">${input('uberWeekly','Uber weekly equipment fee assumption ($)',a.uberWeekly,'.50','1000')}${input('uberSetup','Uber one-time setup assumption ($)',a.uberSetup,'1','10000')}</div><p class="muted">Uber equipment / setup amounts were not established from the current public US pages. Zero here means omitted, not confirmed free. Weekly extras are prorated across ${r.exposureDays} calendar days between the selected shifts, not an actual invoice. Setup is shown separately and not repeated in ongoing costs.</p><div class="form-grid">${input('ddDrive','DoorDash Drive fee / order ($)',a.ddDrive,'.01','100')}${input('uberDirect','Uber Direct fee / order ($)',a.uberDirect,'.01','100')}</div><p class="muted">Published Drive range: $6.99–$10.99; $8.99 is the modeled midpoint. Uber Direct starts at $7.99. Neither is a Seattle-specific quote, and both may vary by fulfillment needs.</p></details><p class="error" id="cost-error" role="alert"></p><div class="actions"><button class="primary" type="submit">Recalculate scenario</button><button type="button" data-cost-reset>Reset assumptions</button></div></form></details>${r.orders?`<div class="report-coverage"><strong>${r.orders} fictional deliveries · ${r.trips} timed trips · ${r.rows.length} sample shifts</strong><span>Timing coverage: ${r.timedOrders} / ${r.orders}</span><span>Departure → last drop-off: ${n(r.outboundMinutes)} min</span><span>Return time included: ${n(r.returnMinutes)} min after merging overlaps</span><span>Sample odometer mileage: ${n(r.miles)} mi</span><small>${r.coverageComplete?'All selected orders have usable trip timing.':'Some timing or mileage is missing. Cost differences and break-even values are withheld.'} The trip-time model is ${n(r.totalMinutes/60)} hours: ${r.recordedReturns} trips use recorded sample returns and ${r.estimatedReturns} use the return allowance.</small></div><details class="card cost-allocation"><summary>Explore full delivery cost allocation, baskets & break-even details</summary><p class="muted">These original charts assign all delivery wages to delivery work. That describes resource use; it is different from the spending that would disappear if outsourced.</p><div class="chart-grid cost-chart-grid">${card('What one delivery costs','Modeled average across the selected fictional orders. Equipment assumptions are included; one-time setup is separate.',r.coverageComplete?comparisonBars(r):'<p class="chart-empty">A complete cost comparison needs trip timing and mileage for every selected delivery.</p>')}${card('Costs across these sample shifts','Same assumed order mix on every shift. Similar fee settings can produce overlapping lines.',r.coverageComplete?cumulative(r):'<p class="chart-empty">Choose records with complete trip timing and mileage to compare cumulative costs.</p>')}${card('Where does the balance change?','What-if test: replace all returns with a time allowance and vary average order value.',sensitivity(state,shifts,r),true)}${card('Menu-based basket examples','These are editable hypotheses about order size, not actual customer purchases.',basketBreakdown(a,r),true)}${card('Break-even average subtotal','Above these basket values, in-house delivery costs less in this limited model; below them, the platform costs less.',`<div class="timing-highlights"><div><strong>${money(r.ddBreakEven)}</strong><span>DoorDash Marketplace</span></div><div><strong>${money(r.uberBreakEven)}</strong><span>Uber Eats Marketplace</span></div></div><p class="muted">Includes modeled equipment allocations; excludes one-time setup. Zero means modeled fixed fees alone meet or exceed in-house cost. Unknown timing yields no threshold.</p>`)}${card('First-period extras','Startup costs belong to the first modeled period, not every shift or every week.',`<dl class="essentials"><dt>DoorDash Marketplace signup</dt><dd>$0 published activation fee</dd><dt>Uber setup assumption</dt><dd>${money(a.uberSetup)} ${a.uberSetup?'entered by you':'· unpriced and omitted'}</dd><dt>Uber first-period model</dt><dd>${money(r.uberFirstPeriod)} including that one-time assumption</dd></dl>`)}</div></details><div class="actions cost-export"><button class="primary" data-action="export-cost-scenario">Download scenario CSV</button><button class="outline" data-action="print-reports">Print / save PDF</button></div>`:'<div class="card chart-empty">No completed sample deliveries in this date range. Choose Monthly, Yearly or another range.</div>'}<section class="card cost-method"><h2>What the comparison includes</h2><p><strong>Business savings:</strong> modeled platform charges + entered replacement kitchen labor − mileage − delivery wages outsourcing would remove − entered app price. Wages paid in both arrangements cancel. The detailed allocation charts still assign all delivery wages to delivery work. Payroll taxes, benefits, insurance, existing ordering / card-processing costs, and net profit are not modeled.</p><p><strong>Platforms:</strong> merchant commissions or per-delivery fulfillment fees. Customer delivery fees, tips, taxes and membership charges are not restaurant costs here. Marketplace plans bundle other services, including processing; existing Smile fees are unknown. No new customers, menu markups, promotions or differences in service quality are assumed.</p><p><strong>Two different products:</strong> Marketplace means orders placed through DoorDash / Uber Eats. Drive / Direct means hiring their courier for an order from your own ordering channel. No delivery request, signup or purchase is made by this demo.</p></section><section class="card cost-sources"><h2>Published facts & sources</h2><p class="muted">Checked ${COST_RESEARCH_DATE}. Research snapshot; rates are not updated automatically and are not a negotiated offer.</p><ul><li>${link('doordash','DoorDash Marketplace')}: published US delivery plans 15%, 25%, 30%; no activation / subscription fee; optional tablet $6 weekly.</li><li>${link('uber','Uber Eats')}: Seattle Lite starts at 15%; Plus 25% (+5 points for Uber One); Premium 30%. ${link('uberSignup','US signup information')} does not establish exact setup / tablet charges.</li><li>${link('drive','DoorDash Drive')}: $6.99–$10.99 per order, no signup / subscription fee. ${link('uber','Uber Direct')}: starts at $7.99.</li><li>${link('seattle','Seattle delivery-fee guidance')}: delivery services capped at 15%; additional agreed services are separate.</li><li>${link('wage','Seattle 2026 minimum wage')}: $21.30 per hour. Your wage and mileage inputs remain editable.</li><li>${link('menu','Srivilai dinner menu')}: basis for the hypothetical baskets, not observed order averages.</li></ul></section>`;}
function baseCSVRows(result){const a=result.assumptions;return [['sample_shift','scenario_only','orders','assumed_average_subtotal','modeled_delivery_minutes','sample_shift_miles','delivery_wage_per_hour','mileage_rate','return_minutes_per_trip','modeled_wages','modeled_mileage','modeled_inhouse_cost','doordash_marketplace','uber_marketplace','doordash_drive','uber_direct','doordash_rate_percent','uber_effective_rate_percent','timing_complete','recorded_sample_returns','estimated_returns','solo_basket','solo_share_percent','duo_basket','duo_share_percent','family_basket','family_share_percent','doordash_tablet_included','uber_weekly_equipment_assumption','uber_one_time_setup_assumption','uber_one_share_percent','doordash_drive_per_order','uber_direct_per_order','research_date'],...result.rows.map(r=>[r.date,'FICTIONAL / HYPOTHETICAL',r.orders,result.average,r.timing.total,r.miles,a.wage,a.mileageRate,a.returnMinutes,r.wages,r.mileage,r.inhouse,r.ddCommission+r.ddEquipment,r.uberCommission+r.uberEquipment,r.ddDrive,r.uberDirect,a.ddRate,result.uberEffectiveRate,result.coverageComplete?'YES':'NO',r.timing.recordedReturns,r.timing.estimatedReturns,a.soloPrice,a.soloShare,a.duoPrice,a.duoShare,a.familyPrice,a.familyShare,a.ddTablet?'YES':'NO',a.uberWeekly,a.uberSetup,a.uberOneShare,a.ddDrive,a.uberDirect,COST_RESEARCH_DATE])];}

export function scenarioCSVRows(result,businessInputs=BUSINESS_DEFAULTS){const rows=baseCSVRows(result),b=businessFromCosts(result,businessInputs),a=b.assumptions;rows[0].push('gross_dd_fees_avoided','gross_uber_fees_avoided','avoidable_delivery_wages_percent','replacement_hours_entire_period_assumption','replacement_hourly_wage','app_price_entire_period_assumption','estimated_net_savings_vs_dd','estimated_net_savings_vs_uber','entry_time_illustration_enabled','entry_seconds_before','entry_seconds_after','entry_time_savings_not_in_financial_totals');for(let i=1;i<rows.length;i++){const r=result.rows[i-1],value=b.cumulative[i-1],previous=b.cumulative[i-2]||{dd:0,uber:0};rows[i].push(r.ddCommission,r.uberCommission,a.avoidablePercent,a.replacementHours,a.replacementWage,a.appCost,result.coverageComplete?value.dd-previous.dd:'',result.coverageComplete?value.uber-previous.uber:'',a.entryScenario?'YES':'NO',a.beforeSeconds,a.afterSeconds,'YES');}return rows;}
